# 105 evidence-informed scenarios: 15 per domain.
# Each scenario has a concrete surface conflict, a latent motive, real constraints,
# an earned-information path and multiple legitimate endings.


def make(label, character, user_role, title, situation, latent, constraints, good_move, failure, layers, endings):
    return {
        'label': label,
        'character': character,
        'title': title,
        'brief': f'את/ה {user_role}. {situation} {character} פותח/ת את השיחה. המטרה שלך היא להבין מה באמת עומד מאחורי ההתנגדות, להגיב באופן מקצועי ולהוביל לתוצאה אמיתית — בלי לחץ, הטעיה או מאבק כוח.',
        'facts': f'''המניע העמוק שאינו נאמר מיד: {latent}\nאילוצים ועובדות: {constraints}\nמהלך איכותי אפשרי: {good_move}\nמה יפגע בשיחה: {failure}\nאל תחשוף את המניע העמוק מיד. חשוף אותו רק אם המתנסה שואל, מקשיב או יוצר מספיק אמון. אם חסם נפתר — אל תמציא התנגדות חדשה.''',
        'layers': layers,
        'possible_endings': endings,
    }

